once('''    const novos = votosDe({ ...(f.votos ?? {}), fixacao: x.fixacao ?? undefined, projecao: x.projecao ?? undefined, total: x.total || f.votos?.total, origem: x.origem ?? "estimativa" } as Partial<Votos>, f.votos?.ocasioes?.length ? f.votos.ocasioes : OCASIOES);\n    const novosDuplicados = novos ? await votosDuplicadosNoAcervo(f.nome, f.casa, novos.fixacao, novos.projecao) : false;\n    if (novos && temVotos(novos.fixacao) && temVotos(novos.projecao) && !votosSuspeitos(novos) && !novosDuplicados) {''','''    const respostaSuspeita = votosSuspeitos({ fixacao: x.fixacao, projecao: x.projecao }, f.nome, f.casa);\n    const novos = respostaSuspeita ? null : votosDe({ ...(f.votos ?? {}), fixacao: x.fixacao ?? undefined, projecao: x.projecao ?? undefined, total: x.total || f.votos?.total, origem: x.origem ?? "estimativa" } as Partial<Votos>, f.votos?.ocasioes?.length ? f.votos.ocasioes : OCASIOES);\n    const novosDuplicados = novos ? await votosDuplicadosNoAcervo(f.nome, f.casa, novos.fixacao, novos.projecao) : false;\n    if (novos && temVotos(novos.fixacao) && temVotos(novos.projecao) && !novosDuplicados) {''','complemento suspeito cru')
